starter:
%dw 2.0
type ClickEvent = { x: Number, y: Number }
type KeyEvent = { key: String }
output application/json
---
payload map (e) -> {
  id: e.id,
  "type": if (e is KeyEvent) "Key" else if (e is ClickEvent) "Click" else "Unknown"
}

